	/**
	 * Method to retrieve the DataSet via DataSetFetchOneSummary
	 * @param 	summary DataSetFetchOneSummary
	 * @return 	DataSetFetchOneResponse
	 */
	public DataSet getDataSet( DataSetFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "DataSetFetchOneSummary arg cannot be null" );

		DataSet entity = null;
		UUID id = summary.getDataSetId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a DataSet using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all DataSets
	 *
	 * @return 	List<DataSet>
	 */
    public List<DataSet> getAllDataSet() {
		List<DataSet> list = projector.findAll( new FindAllDataSetQuery() );
		return list;
	}

